      <app-sheet-picker />
      <app-sheet-today />
      <app-sheet-as-of />
      @if (session.sheet()) {
        <app-settings />
        <app-holidays />
      }
      <app-people />
      @if (!session.sheet()) {
        <p data-testid="home-empty">Load a sheet to begin.</p>
      }
    } @else {
      <app-sign-in />
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
}
